<https://example.org/shapes/FrameAttachmentRecordShape> a sh:NodeShape ;
    sh:targetClass <https://w3id.org/nltl/vocab#frameAttachmentRecord> ;
    sh:property [
        sh:path <https://w3id.org/nltl/vocab#frameShellWeldType> ;
        sh:hasValue <https://w3id.org/nltl/vocab#doubleContinuousWeld> ;
        sh:message "Frame must be attached by a double continuous weld." ;
    ] ;
    sh:property [
        sh:path <https://w3id.org/nltl/vocab#scallopingPresent> ;
        sh:datatype xsd:boolean ;
        sh:maxCount 1 ;
        sh:minCount 1 ;
        sh:message "Scalloping presence must be specified." ;
    ] ;
    sh:property [
        sh:path <https://w3id.org/nltl/vocab#shellPlateButtCrossing> ;
        sh:datatype xsd:boolean ;
        sh:maxCount 1 ;
        sh:minCount 1 ;
        sh:message "Shell plate butt crossing must be specified." ;
    ] ;
    sh:if [
        sh:property [
            sh:path <https://w3id.org/nltl/vocab#scallopingPresent> ;
            sh:hasValue true ;
        ]
    ] ;
    sh:then [
        sh:property [
            sh:path <https://w3id.org/nltl/vocab#shellPlateButtCrossing> ;
            sh:hasValue true ;
            sh:message "If scalloping is present, shell plate butt crossing must be true (exception allowed)." ;
        ]
    ] .

